CREATE TABLE commerce_user (id BIGSERIAL PRIMARY KEY,email VARCHAR(254) NOT NULL,name VARCHAR(100) NOT NULL,password_hash VARCHAR(255) NOT NULL,role VARCHAR(20) NOT NULL CHECK(role IN ('CUSTOMER','SELLER','ADMIN')),active BOOLEAN NOT NULL DEFAULT TRUE,created_at TIMESTAMPTZ NOT NULL,updated_at TIMESTAMPTZ NOT NULL,CONSTRAINT uk_user_email UNIQUE(email));
CREATE TABLE address (id BIGSERIAL PRIMARY KEY,user_id BIGINT NOT NULL REFERENCES commerce_user(id),recipient VARCHAR(120) NOT NULL,line1 VARCHAR(200) NOT NULL,line2 VARCHAR(200),city VARCHAR(100) NOT NULL,postal_code VARCHAR(30) NOT NULL,country_code VARCHAR(2) NOT NULL,created_at TIMESTAMPTZ NOT NULL,updated_at TIMESTAMPTZ NOT NULL); CREATE INDEX ix_address_user ON address(user_id);
CREATE TABLE category (id BIGSERIAL PRIMARY KEY,name VARCHAR(100) NOT NULL,description VARCHAR(500),active BOOLEAN NOT NULL DEFAULT TRUE,created_at TIMESTAMPTZ NOT NULL,updated_at TIMESTAMPTZ NOT NULL,CONSTRAINT uk_category_name UNIQUE(name));
CREATE TABLE product (id BIGSERIAL PRIMARY KEY,name VARCHAR(160) NOT NULL,description VARCHAR(4000) NOT NULL,price NUMERIC(19,2) NOT NULL CHECK(price>0),image_url VARCHAR(1000),active BOOLEAN NOT NULL DEFAULT TRUE,category_id BIGINT NOT NULL REFERENCES category(id),seller_id BIGINT NOT NULL REFERENCES commerce_user(id),created_at TIMESTAMPTZ NOT NULL,updated_at TIMESTAMPTZ NOT NULL); CREATE INDEX ix_product_active ON product(active);CREATE INDEX ix_product_seller ON product(seller_id);CREATE INDEX ix_product_category ON product(category_id);
CREATE TABLE inventory (id BIGSERIAL PRIMARY KEY,product_id BIGINT NOT NULL REFERENCES product(id),available_quantity INT NOT NULL CHECK(available_quantity>=0),reserved_quantity INT NOT NULL DEFAULT 0 CHECK(reserved_quantity>=0),version BIGINT NOT NULL DEFAULT 0,created_at TIMESTAMPTZ NOT NULL,updated_at TIMESTAMPTZ NOT NULL,CONSTRAINT uk_inventory_product UNIQUE(product_id));
CREATE TABLE cart (id BIGSERIAL PRIMARY KEY,user_id BIGINT NOT NULL REFERENCES commerce_user(id),created_at TIMESTAMPTZ NOT NULL,updated_at TIMESTAMPTZ NOT NULL,CONSTRAINT uk_cart_user UNIQUE(user_id));
CREATE TABLE cart_item (id BIGSERIAL PRIMARY KEY,cart_id BIGINT NOT NULL REFERENCES cart(id) ON DELETE CASCADE,product_id BIGINT NOT NULL REFERENCES product(id),quantity INT NOT NULL CHECK(quantity>0),created_at TIMESTAMPTZ NOT NULL,updated_at TIMESTAMPTZ NOT NULL,CONSTRAINT uk_cart_product UNIQUE(cart_id,product_id));
CREATE TABLE wishlist_item (id BIGSERIAL PRIMARY KEY,user_id BIGINT NOT NULL REFERENCES commerce_user(id),product_id BIGINT NOT NULL REFERENCES product(id),created_at TIMESTAMPTZ NOT NULL,updated_at TIMESTAMPTZ NOT NULL,CONSTRAINT uk_wishlist_user_product UNIQUE(user_id,product_id));
CREATE TABLE coupon (id BIGSERIAL PRIMARY KEY,code VARCHAR(40) NOT NULL,type VARCHAR(15) NOT NULL,value NUMERIC(19,2) NOT NULL CHECK(value>0),minimum_order_value NUMERIC(19,2) NOT NULL DEFAULT 0,maximum_discount NUMERIC(19,2),starts_at TIMESTAMPTZ NOT NULL,expires_at TIMESTAMPTZ NOT NULL,usage_limit INT NOT NULL CHECK(usage_limit>0),per_user_limit INT NOT NULL CHECK(per_user_limit>0),active BOOLEAN NOT NULL,created_at TIMESTAMPTZ NOT NULL,updated_at TIMESTAMPTZ NOT NULL,CONSTRAINT uk_coupon_code UNIQUE(code),CHECK(starts_at<expires_at));
CREATE TABLE customer_order (id BIGSERIAL PRIMARY KEY,user_id BIGINT NOT NULL REFERENCES commerce_user(id),status VARCHAR(30) NOT NULL,subtotal NUMERIC(19,2) NOT NULL,discount NUMERIC(19,2) NOT NULL,total NUMERIC(19,2) NOT NULL,coupon_code VARCHAR(40),delivery_address VARCHAR(500) NOT NULL,created_at TIMESTAMPTZ NOT NULL,updated_at TIMESTAMPTZ NOT NULL);CREATE INDEX ix_order_user ON customer_order(user_id);CREATE INDEX ix_order_status ON customer_order(status);CREATE INDEX ix_order_created ON customer_order(created_at);
CREATE TABLE order_item (id BIGSERIAL PRIMARY KEY,order_id BIGINT NOT NULL REFERENCES customer_order(id) ON DELETE CASCADE,product_id BIGINT NOT NULL,product_name VARCHAR(160) NOT NULL,unit_price NUMERIC(19,2) NOT NULL,quantity INT NOT NULL,line_total NUMERIC(19,2) NOT NULL,created_at TIMESTAMPTZ NOT NULL,updated_at TIMESTAMPTZ NOT NULL);CREATE INDEX ix_order_item_product ON order_item(product_id);
CREATE TABLE coupon_usage (id BIGSERIAL PRIMARY KEY,coupon_id BIGINT NOT NULL REFERENCES coupon(id),user_id BIGINT NOT NULL REFERENCES commerce_user(id),order_id BIGINT NOT NULL REFERENCES customer_order(id),created_at TIMESTAMPTZ NOT NULL,updated_at TIMESTAMPTZ NOT NULL);CREATE INDEX ix_coupon_usage_coupon ON coupon_usage(coupon_id);CREATE INDEX ix_coupon_usage_user ON coupon_usage(user_id);
CREATE TABLE order_status_history (id BIGSERIAL PRIMARY KEY,order_id BIGINT NOT NULL REFERENCES customer_order(id),from_status VARCHAR(30) NOT NULL,to_status VARCHAR(30) NOT NULL,changed_by VARCHAR(254) NOT NULL,created_at TIMESTAMPTZ NOT NULL,updated_at TIMESTAMPTZ NOT NULL);CREATE INDEX ix_status_history_order ON order_status_history(order_id);
CREATE TABLE payment (id BIGSERIAL PRIMARY KEY,order_id BIGINT NOT NULL REFERENCES customer_order(id),idempotency_key VARCHAR(100) NOT NULL,request_fingerprint VARCHAR(64) NOT NULL,amount NUMERIC(19,2) NOT NULL,status VARCHAR(20) NOT NULL,provider_reference VARCHAR(100) NOT NULL,created_at TIMESTAMPTZ NOT NULL,updated_at TIMESTAMPTZ NOT NULL,CONSTRAINT uk_payment_idempotency UNIQUE(idempotency_key));CREATE INDEX ix_payment_order ON payment(order_id);
CREATE TABLE review (id BIGSERIAL PRIMARY KEY,user_id BIGINT NOT NULL REFERENCES commerce_user(id),product_id BIGINT NOT NULL REFERENCES product(id),rating INT NOT NULL CHECK(rating BETWEEN 1 AND 5),comment VARCHAR(2000) NOT NULL,verified_purchase BOOLEAN NOT NULL,created_at TIMESTAMPTZ NOT NULL,updated_at TIMESTAMPTZ NOT NULL,CONSTRAINT uk_review_user_product UNIQUE(user_id,product_id));CREATE INDEX ix_review_product ON review(product_id);
CREATE TABLE notification (id BIGSERIAL PRIMARY KEY,user_id BIGINT NOT NULL REFERENCES commerce_user(id),type VARCHAR(40) NOT NULL,message VARCHAR(1000) NOT NULL,delivered BOOLEAN NOT NULL DEFAULT FALSE,created_at TIMESTAMPTZ NOT NULL,updated_at TIMESTAMPTZ NOT NULL);CREATE INDEX ix_notification_user ON notification(user_id);
CREATE TABLE audit_log (id BIGSERIAL PRIMARY KEY,entity_type VARCHAR(50) NOT NULL,entity_id VARCHAR(100) NOT NULL,action VARCHAR(50) NOT NULL,previous_value VARCHAR(4000),new_value VARCHAR(4000),actor VARCHAR(254) NOT NULL,correlation_id VARCHAR(100),created_at TIMESTAMPTZ NOT NULL,updated_at TIMESTAMPTZ NOT NULL);CREATE INDEX ix_audit_entity ON audit_log(entity_type,entity_id);CREATE INDEX ix_audit_actor ON audit_log(actor);
